// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * End-to-end guards for the {@code QueryModelNormalizerOptimizer} rewrite that pushes a constant VALUES relation
 * through a variable-scope-changing BIND. The push turns the unbound evaluation of the group into bound probes, so a
 * Filter inside the group that observes whether the pushed variable is bound ({@code !BOUND}, {@code NOT EXISTS}) must
 * block the push unless its own argument already assures the variable.
 */
public class ScopedBindValuesPushSoundnessTest {

	private static final String PREFIX = "PREFIX : <http://ex/>\n";
	private static final String ONE = "\"1\"^^<http://www.w3.org/2001/XMLSchema#integer>";

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private void load(String trig) throws Exception {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader("@prefix : <http://ex/> .\n" + trig), "http://ex/", RDFFormat.TRIG);
		}
	}

	private List<String> rows(String query, String... vars) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(PREFIX + query);
			List<String> result = new ArrayList<>();
			try (TupleQueryResult res = tupleQuery.evaluate()) {
				for (BindingSet bs : res) {
					StringBuilder sb = new StringBuilder();
					for (String var : vars) {
						sb.append(var).append('=').append(bs.getValue(var)).append(' ');
					}
					result.add(sb.toString().trim());
				}
			}
			return result.stream().sorted().collect(Collectors.toList());
		}
	}

	@Test
	public void valuesIsNotPushedThroughScopedBindWhenInnerFilterObservesNotBound() throws Exception {
		load(":g { :s1 :p :o1 . }\n");
		String query = "SELECT ?x ?s ?one WHERE {\n"
				+ "  VALUES ?x { :a :b }\n"
				+ "  { GRAPH :g { VALUES ?x { UNDEF } ?s :p ?o FILTER(!BOUND(?x)) } BIND(1 AS ?one) }\n"
				+ "}";
		// inner group: x unbound -> filter true -> (s1, one=1); joined with VALUES x in {a,b} -> 2 rows
		assertEquals(List.of("x=http://ex/a s=http://ex/s1 one=" + ONE, "x=http://ex/b s=http://ex/s1 one=" + ONE),
				rows(query, "x", "s", "one"));
	}

	@Test
	public void valuesIsNotPushedThroughScopedBindWhenInnerFilterObservesNotExists() throws Exception {
		load(":g { :s1 :p :o1 . :s1 :q :c . }\n");
		String query = "SELECT ?x ?s WHERE {\n"
				+ "  VALUES ?x { :a :b }\n"
				+ "  { GRAPH :g { VALUES ?x { UNDEF } ?s :p ?o FILTER NOT EXISTS { ?s :q ?x } } BIND(1 AS ?one) }\n"
				+ "}";
		// inner group: x unbound -> NOT EXISTS { :s1 :q ?x } is false (:c exists) -> no rows
		assertEquals(List.of(), rows(query, "x", "s"));
	}

	@Test
	public void valuesIsNotPushedThroughScopedBindWhoseExpressionMentionsTheVariable() throws Exception {
		// control: BIND expression mentions ?x, so the normalizer never pushes the VALUES
		load(":g { :s1 :p :o1 . }\n");
		String query = "SELECT ?x ?s WHERE {\n"
				+ "  VALUES ?x { :a :b }\n"
				+ "  { GRAPH :g { VALUES ?x { UNDEF } ?s :p ?o FILTER(!BOUND(?x)) } BIND(COALESCE(?x, 1) AS ?one) }\n"
				+ "}";
		assertEquals(List.of("x=http://ex/a s=http://ex/s1", "x=http://ex/b s=http://ex/s1"), rows(query, "x", "s"));
	}

	@Test
	public void valuesPushedThroughScopedBindWhenInnerPatternAssuresTheVariableKeepsResults() throws Exception {
		load(":g { :a :p :o1 . :b :p :o2 . :c :p :o3 . :a :q :c . }\n");
		String query = "SELECT ?x ?o ?one WHERE {\n"
				+ "  VALUES ?x { :a :b }\n"
				+ "  { GRAPH :g { ?x :p ?o FILTER NOT EXISTS { ?x :q ?z } } BIND(1 AS ?one) }\n"
				+ "}";
		// ?x is assured inside the group, so the push is sound: :a is excluded by NOT EXISTS, :b survives
		assertEquals(List.of("x=http://ex/b o=http://ex/o2 one=" + ONE), rows(query, "x", "o", "one"));
	}
}
